private void xrPivotGrid1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
		xrPivotGrid1.BestFit();
            xrPivotGrid1.CanGrow = true;
            xrPivotGrid1.CanShrink = true;
         }

private void xrPivotGrid1_FieldValueDisplayText(object sender, DevExpress.XtraReports.UI.PivotGrid.PivotFieldDisplayTextEventArgs e) {

            if (e.ValueType == DevExpress.XtraPivotGrid.PivotGridValueType.GrandTotal && e.DisplayText == "Grand Total")
            {
                e.DisplayText = "Totali";
            }
}

private void xrPivotGrid1_CustomFieldSort(object sender, DevExpress.XtraReports.UI.PivotGrid.PivotGridCustomFieldSortEventArgs e) {

	            if (e.Field.FieldName == "muaj")
	            {
				int vl1 ;
				int vl2 ;
				int m1;
				int m2 ;

				if (e.GetListSourceColumnValue(e.ListSourceRowIndex1, "ROWID") != null)
					{
	                			vl1 = Convert.ToInt32(e.GetListSourceColumnValue(e.ListSourceRowIndex1, "ROWID"));
	                			vl2 = Convert.ToInt32(e.GetListSourceColumnValue(e.ListSourceRowIndex2, "ROWID"));
					}
				else
					{
						vl1 = 0;
						vl2 = 0;
					}
				if((e.GetListSourceColumnValue(e.ListSourceRowIndex1, "muajnr")) != null)
					{
	                			m1 = Convert.ToInt32(e.GetListSourceColumnValue(e.ListSourceRowIndex1, "muajnr"));
	                			m2 = Convert.ToInt32(e.GetListSourceColumnValue(e.ListSourceRowIndex2, "muajnr"));
					}
				else 
					{
						m1 =0;
						m2 = 0;
					}
	                if (m1 == m2)
	                {
	                    e.Result = -1*vl1.CompareTo(vl2);

	                }
	                else
	                    e.Result = m1.CompareTo(m2);
	                e.Handled = true;	}

             if (e.Field.FieldName == "EMRIAGJENTSHITJE")
            {
                 object orderValue1 = e.GetListSourceColumnValue(e.ListSourceRowIndex1, "EMRIAGJENTSHITJE"),
                orderValue2 = e.GetListSourceColumnValue(e.ListSourceRowIndex2, "EMRIAGJENTSHITJE");
                int comparison;

                if (orderValue1.ToString() != "Pa agjent" && orderValue2.ToString() == "Pa agjent")
                {
                 comparison = Comparer.Default.Compare(0, 1);

                }else if (orderValue2.ToString() != "Pa agjent" && orderValue1.ToString() == "Pa agjent")
                {
                    comparison = Comparer.Default.Compare(1, 0);

                } else
                {
                    comparison = Comparer.Default.Compare(orderValue1, orderValue2);
                }

                e.Result = comparison;
                e.Handled = true;
                return;            }        
}



private void xrPivotGrid1_CustomGroupInterval(object sender, DevExpress.XtraReports.UI.PivotGrid.PivotCustomGroupIntervalEventArgs e) 
{
  e.GroupValue = e.Value.ToString();
}
